import sys
from collections import defaultdict

def lca(x, y, fees):
    cost = 0
    while x != y:
        if x < y:
            x, y = y, x
        cost += fees[x]
        x //= 2
    return cost

q = int(sys.stdin.readline())
fees = defaultdict(int)
results = []

for _ in range(q):
    event = sys.stdin.readline().split()
    if event[0] == '1':
        v, u, w = map(int, event[1:])
        while v != u:
            if v < u:
                v, u = u, v
            fees[v] += w
            v //= 2
    else:
        v, u = map(int, event[1:])
        results.append(lca(v, u, fees))

for result in results:
    print(result)
